sys_script_include.script:
var AutoCareUIDataAjax = Class.create();

AutoCareUIDataAjax.prototype = Object.extendsObject(AbstractAjaxProcessor, {

    getData: function() {

        var result = {
            success: true,
            error: '',
            vehicles: 0,
            appointments: 0,
            inspections: 0,
            recommendations: 0,
            repairPlans: 0,
            serviceOutcomes: 0,
            serviceHistory: 0,
            invoices: 0
        };

        try {

            result.vehicles = this.countTable(
                'x_1947064_autoca_0_vehicle'
            );

            result.appointments = this.countTable(
                'x_1947064_autoca_0_appointment'
            );

            result.inspections = this.countTable(
                'x_1947064_autoca_0_inspection'
            );

            result.recommendations = this.countTable(
                'x_1947064_autoca_0_reccommendation'
            );

            result.repairPlans = this.countTable(
                'x_1947064_autoca_0_repair_plan'
            );

            result.serviceOutcomes = this.countTable(
                'x_1947064_autoca_0_service_outcome'
            );

            result.serviceHistory = this.countTable(
                'x_1947064_autoca_0_service_history'
            );

            result.invoices = this.countTable(
                'x_1947064_autoca_0_invoice'
            );

        } catch (e) {

            result.success = false;
            result.error = String(e);

        }

        return JSON.stringify(result);
    },


    countTable: function(tableName) {

        var gr = new GlideRecordSecure(tableName);

        if (!gr.isValid()) {
            throw new Error(
                'Invalid table: ' + tableName
            );
        }

        gr.query();

        return gr.getRowCount();
    },


    testInspection: function() {

        var result = {
            success: true,
            table: 'x_1947064_autoca_0_inspection',
            count: 0,
            error: ''
        };

        try {

            var gr = new GlideRecordSecure(
                'x_1947064_autoca_0_inspection'
            );

            if (!gr.isValid()) {
                throw new Error(
                    'Inspection table is invalid'
                );
            }

            gr.query();

            result.count = gr.getRowCount();

        } catch (e) {

            result.success = false;
            result.error = String(e);

        }

        return JSON.stringify(result);
    },


    type: 'AutoCareUIDataAjax'

});
